    for i,r in enumerate(rows):axes[0].text(values[i]+1,i,f"{values[i]:.1f}% (n={r['comparisons']['baseline']['paired_instances']})",fontsize=8,va='center')
    axes[0].set(yticks=y,yticklabels=labels,xlim=(0,72),xlabel='Mean paired cost reduction (%)',title='Certified feasible ILP/baseline pairs');axes[0].invert_yaxis()
