    story=[Spacer(1,48),P('OPTIMIZATION TECHNIQUES','heading'),Spacer(1,25),Paragraph('OPTIMIZE<br/>ANYTHING',ParagraphStyle('cover',fontName='DVS-Bold',fontSize=38,leading=44,textColor=colors.HexColor('#173d61'))),Spacer(1,25),P('Assignment 8 - Integrated technical report','heading'),Spacer(1,20),P('Akshat Tikaria'),P('Roll number: 241070005'),P('B.Tech Computer Science - Third year'),Spacer(1,18),P('Main case study: EV charging scheduling'),P('Experimental portfolio: Tracks A-J'),P('Updated: 7 November 2026'),Spacer(1,25),P('Formulate. Compare. Verify. Explain the trade-offs.','heading'),P('Includes the original evidence, additional chapter demonstrations, source-linked research experiments, exact coverage mapping and submission checklist.','small'),PageBreak()]
